package energy;/** * EU能量能力适配器 * <p> * 将 {@link EUEnergyStorage} 适配为 {@link EUCapability} 接口， * 用于机器方块实体的能量能力注册。 * </p> */public class EUEnergyCapabilityAdapter implements EUCapability {    private final EUEnergyStorage energyStorage;    private final EUVoltage voltage;    public EUEnergyCapabilityAdapter(EUEnergyStorage energyStorage, EUVoltage voltage) {        this.energyStorage = energyStorage;        this.voltage = voltage;    }    @Override    public long receiveEnergy(long maxReceive, boolean simulate) {        return energyStorage.receiveEnergy(maxReceive, simulate);    }    @Override    public long extractEnergy(long maxExtract, boolean simulate) {        return energyStorage.extractEnergy(maxExtract, simulate);    }    @Override    public long getEnergyStored() {        return energyStorage.getEnergyStored();    }    @Override    public long getMaxEnergyStored() {        return energyStorage.getMaxEnergyStored();    }    @Override    public EUVoltage getVoltage() {        return voltage;    }    @Override    public long getMaxTransferRate() {        return energyStorage.getMaxTransferRate();    }    @Override    public boolean canReceive() {        return true;    }    @Override    public boolean canExtract() {        return true;    }}